using System.Collections.Generic;

namespace SunnyValley.Core.Meta
{
    // The economy data: Resources/Meta/balance.json, generated by farm/tools/economy.py (never edited by hand).
    // All times are in seconds, all prices in whole coins / crystals.

    public sealed class Balance
    {
        public int Version;
        public string GeneratedBy;
        public StartDef Start = new StartDef();
        public LivesDef Lives = new LivesDef();
        public Match3Def Match3 = new Match3Def();
        public List<BoosterDef> Boosters = new List<BoosterDef>();
        public List<ToolDef> Tools = new List<ToolDef>();
        public List<ItemDef> Items = new List<ItemDef>();
        public List<CropDef> Crops = new List<CropDef>();
        public List<TreeDef> Trees = new List<TreeDef>();
        public List<AnimalHouseDef> AnimalHouses = new List<AnimalHouseDef>();
        public List<AnimalDef> Animals = new List<AnimalDef>();
        public List<WorkshopDef> Workshops = new List<WorkshopDef>();
        public BarnDef Barn = new BarnDef();
        public PlotsDef Plots = new PlotsDef();
        public List<ExpansionDef> Expansions = new List<ExpansionDef>();
        public ToolDropsDef ToolDrops = new ToolDropsDef();
        public List<LevelDef> Levels = new List<LevelDef>();
        public OrdersDef Orders = new OrdersDef();
        public TruckDef Truck = new TruckDef();
        public TownDef Town = new TownDef();
        public DailyDef Daily = new DailyDef();
        public SpeedUpDef SpeedUp = new SpeedUpDef();
        public FarmStartDef FarmStart = new FarmStartDef();
        public PacingDef Pacing = new PacingDef();
    }

    public sealed class StartDef
    {
        public int Coins;
        public int Crystals;
        public int Stars;
        public SortedDictionary<string, int> Boosters = new SortedDictionary<string, int>();
        public SortedDictionary<string, int> Tools = new SortedDictionary<string, int>();
    }

    /// <summary>GDD 4.6: 5 lives, one every 30 minutes.</summary>
    public sealed class LivesDef
    {
        public int Max = 5;
        public int RegenSeconds = 1800;
        public int RefillCrystals;
    }

    /// <summary>What the meta gives for match-3 levels (GDD 3, 4.7).</summary>
    public sealed class Match3Def
    {
        /// <summary>Coins for every won level on top of what the board itself paid.</summary>
        public int WinCoins;
        /// <summary>+5 moves after running out (GDD 4.7).</summary>
        public int ExtraMoves = 5;
        /// <summary>900, 1900, 2900 — the last price repeats.</summary>
        public List<int> ExtraMovesPrices = new List<int>();
        /// <summary>Every N-th level is a milestone with <see cref="MilestoneReward"/>.</summary>
        public int MilestoneEvery;
        public Reward MilestoneReward = new Reward();
        /// <summary>Every N-th win gives the next booster from <see cref="BoosterRotation"/>.</summary>
        public int BoosterEvery;
        public List<string> BoosterRotation = new List<string>();
        /// <summary>Chance (percent) that a won level also gives a tool, once the farm is open.</summary>
        public int ToolPercent;
    }

    public sealed class BoosterDef
    {
        public string Id;
        public string Name;
        /// <summary>"pre" (chosen before the level) or "in" (used during the level).</summary>
        public string Kind;
        /// <summary>Shop price in coins.</summary>
        public int Coins;
        public string Description;
    }

    public sealed class ToolDef
    {
        public string Id;
        public string Name;
        /// <summary>"barn" (hammer, nails, paint) or "land" (saw, axe).</summary>
        public string Kind;
    }

    /// <summary>A good kept in the barn. Prices and XP are computed by the economy model from its production chain.</summary>
    public sealed class ItemDef
    {
        public string Id;
        public string Name;
        public string Kind;
        /// <summary>Farm level at which it can first be produced.</summary>
        public int Level;
        /// <summary>Coins for selling one from the barn.</summary>
        public int Sell;
        /// <summary>Coins one unit is worth in an order.</summary>
        public int OrderCoins;
        /// <summary>XP one unit is worth in an order.</summary>
        public int Xp;
        /// <summary>The model's work estimate for one unit, minutes (documentation and order sizes).</summary>
        public double Work;
    }

    public sealed class CropDef
    {
        public string Item;
        public int GrowSeconds;
        /// <summary>Coins for a seed when the barn has none of this crop (planting uses one from the barn first).</summary>
        public int SeedCoins;
        /// <summary>Units harvested from one plot.</summary>
        public int Yield = 2;
    }

    public sealed class TreeDef
    {
        public string Id;
        public string Name;
        public string Item;
        public int Level;
        public int CycleSeconds;
        public int Yield;
        /// <summary>Price of the 1st, 2nd… tree of this kind (count = the maximum).</summary>
        public List<int> Costs = new List<int>();
    }

    public sealed class AnimalHouseDef
    {
        public string Id;
        public string Name;
        public int Level;
        public int Coins;
        public int Population;
        public int Capacity;
    }

    public sealed class AnimalDef
    {
        public string Id;
        public string Name;
        public string House;
        public string Product;
        /// <summary>One unit of this item (from the barn) feeds the animal once.</summary>
        public string Feed;
        public int Seconds;
        public int Level;
        /// <summary>Price of the 1st, 2nd… animal (count = the maximum, never above the house capacity).</summary>
        public List<int> Costs = new List<int>();
    }

    public sealed class WorkshopDef
    {
        public string Id;
        public string Name;
        public int Level;
        public int Coins;
        public int Population;
        /// <summary>Queue slots the workshop starts with.</summary>
        public int Slots;
        /// <summary>Crystal prices of the extra slots, in order.</summary>
        public List<int> SlotCrystals = new List<int>();
        public List<RecipeDef> Recipes = new List<RecipeDef>();
    }

    public sealed class RecipeDef
    {
        public string Id;
        public int Level;
        public SortedDictionary<string, int> Inputs = new SortedDictionary<string, int>();
        /// <summary>An item id, or a booster id (the tool shed makes boosters, GDD 6).</summary>
        public string Output;
        public int Count = 1;
        public int Seconds;
    }

    public sealed class BarnDef
    {
        public int Capacity;
        public List<BarnUpgradeDef> Upgrades = new List<BarnUpgradeDef>();
    }

    public sealed class BarnUpgradeDef
    {
        /// <summary>Capacity added by this upgrade.</summary>
        public int Capacity;
        public SortedDictionary<string, int> Tools = new SortedDictionary<string, int>();
    }

    public sealed class PlotsDef
    {
        /// <summary>Plots the restored vegetable garden gives at the end of chapter 1.</summary>
        public int Start;
        /// <summary>Extra plots for sale, in order.</summary>
        public List<PlotOfferDef> Offers = new List<PlotOfferDef>();
    }

    public sealed class PlotOfferDef
    {
        public int Level;
        public int Coins;
    }

    /// <summary>Land expansion for the town (GDD 6): saw and axe clear a lot for more houses and services.</summary>
    public sealed class ExpansionDef
    {
        public string Id;
        public string Name;
        public int Level;
        public int Coins;
        public SortedDictionary<string, int> Tools = new SortedDictionary<string, int>();
        /// <summary>Building lots the expansion opens.</summary>
        public int Lots;
    }

    public sealed class ToolDropsDef
    {
        /// <summary>Chance per harvest (plot, tree, animal) to find a tool.</summary>
        public int HarvestPercent;
        /// <summary>Chance that an order also pays a tool.</summary>
        public int OrderPercent;
        /// <summary>From this farm level saw and axe drop too.</summary>
        public int LandFromLevel;
        /// <summary>Share (percent) of drops that are land tools once they can drop.</summary>
        public int LandSharePercent;
    }

    public sealed class LevelDef
    {
        public int Level;
        /// <summary>Total XP needed to reach this level.</summary>
        public int Xp;
        public Reward Reward = new Reward();
    }

    public sealed class OrdersDef
    {
        public int Slots = 9;
        public int FulfillCooldownSeconds;
        public int DiscardCooldownSeconds;
        /// <summary>Per farm level (index = level-1, last value repeats): the longest production chain an order may ask for, minutes.</summary>
        public List<int> MaxChainMinutes = new List<int>();
        /// <summary>Per farm level: up to how many different goods one order asks.</summary>
        public List<int> MaxKinds = new List<int>();
        /// <summary>Per farm level: total work (model minutes) one order may ask for.</summary>
        public List<int> MaxWorkMinutes = new List<int>();
        /// <summary>Per farm level: the most units of one good in one order.</summary>
        public List<int> MaxUnits = new List<int>();
        /// <summary>Order pays this percent of the goods' order value.</summary>
        public int CoinPercent = 100;
        public int XpPercent = 100;
    }

    public sealed class TruckDef
    {
        public int Level;
        public int Crates = 3;
        /// <summary>Units per crate scale: crate asks MaxUnits × this percent.</summary>
        public int UnitsPercent;
        public int ReturnSeconds;
        public int CoinPercent;
        public int XpPercent;
        /// <summary>Tools paid by every truck.</summary>
        public int Tools;
    }

    public sealed class TownDef
    {
        /// <summary>Lots for houses and services before any land expansion.</summary>
        public int BaseLots;
        /// <summary>Population the farm supports without service buildings.</summary>
        public int BasePopulationCap;
        public List<TownBuildingDef> Houses = new List<TownBuildingDef>();
        public List<TownBuildingDef> Services = new List<TownBuildingDef>();
        public List<TownBuildingDef> Decorations = new List<TownBuildingDef>();
    }

    public sealed class TownBuildingDef
    {
        public string Id;
        public string Name;
        public string Kind;
        public int Level;
        public int Coins;
        /// <summary>Special buildings are paid with stars (GDD 6: stars open special buildings).</summary>
        public int Stars;
        /// <summary>House: residents it adds.</summary>
        public int Population;
        /// <summary>Service: how many residents it lets the town hold.</summary>
        public int Capacity;
        public int Beauty;
        public int Xp;
        /// <summary>How many can be built (0 = unlimited).</summary>
        public int Max;
    }

    public sealed class DailyDef
    {
        public int PerDay = 3;
        public List<DailyTaskDef> Tasks = new List<DailyTaskDef>();
        /// <summary>Extra reward when all tasks of the day are done.</summary>
        public Reward Chest = new Reward();
        /// <summary>Login gifts, a 7-day cycle; a missed day does not reset it (GDD 2: no pressure).</summary>
        public List<Reward> Login = new List<Reward>();
    }

    public sealed class DailyTaskDef
    {
        public string Id;
        public string Kind;
        public int Target;
        public string Text;
        /// <summary>Needs the farm economy (chapter 1 finished).</summary>
        public bool Farm;
        public Reward Reward = new Reward();
    }

    public sealed class SpeedUpDef
    {
        /// <summary>One crystal skips this many seconds (rounded up).</summary>
        public int SecondsPerCrystal;
        public int MinCrystals = 1;
    }

    /// <summary>What the restored farm already has when chapter 1 ends.</summary>
    public sealed class FarmStartDef
    {
        public SortedDictionary<string, int> Trees = new SortedDictionary<string, int>();
        public SortedDictionary<string, int> Animals = new SortedDictionary<string, int>();
        public List<string> AnimalHouses = new List<string>();
        public List<string> Workshops = new List<string>();
        public SortedDictionary<string, int> Items = new SortedDictionary<string, int>();
        public SortedDictionary<string, int> Town = new SortedDictionary<string, int>();
    }

    /// <summary>The model's pacing: the player bot test checks the real rules against these numbers.</summary>
    public sealed class PacingDef
    {
        /// <summary>Local hours of the model player's sessions.</summary>
        public List<double> SessionHours = new List<double>();
        public int AttemptsPerSession;
        public double WinRate;
        public double LevelMinutes;
        public double Chapter1MinDays;
        public double Chapter1MaxDays;
        /// <summary>The model's day (since install) when chapter 1 ends.</summary>
        public double Chapter1Day;
        /// <summary>Farm level → model day (since install) it is reached.</summary>
        public SortedDictionary<int, double> LevelDays = new SortedDictionary<int, double>();
        /// <summary>Allowed deviation of the bot from the model, percent.</summary>
        public int TolerancePercent;
    }
}
